import sys; sys.path.insert(0,'/tmp/explore/drill-selection')
from gen import *
# Big deck: 12 "due" cards (deck Due) + 12 "new" cards (deck New) - but decks matter for from-deck; use one deck for now
txt = '\n\n'.join('Q: q%02d\nA: a%02d'%(i,i) for i in range(1,25))
d = mkcoll('gB', {'Big': txt})
populate(d)
e = export(d)
m = {c['hash']: c['content']['basic']['question'] for c in e['cards']}
import json; json.dump(m, open('/tmp/explore/drill-selection/gB_map.json','w'))
rev = {v:k for k,v in m.items()}
# q01..q12 due (staggered past dates), q13..q24 new
plan={}
for i in range(1,13): plan[rev['q%02d'%i]] = '2026-07-%02d'%(i+10)   # 2026-07-11 .. 2026-07-22
for i in range(13,25): plan[rev['q%02d'%i]] = None
setdue(d, plan)
snap(d)
print('ready', len(m))
for h,due,rc,_ in dump(d): print(m[h], due, rc)
